1	export class BoundedStack {
2	  constructor(capacity) { this.capacity = capacity; this.items = []; }
3	  push(value) { if (this.items.length >= this.capacity) throw new RangeError("stack full"); this.items.push(value); }
4	  pop() { return this.items.pop(); }
5	  // 空栈返回 undefined，与存入 undefined 的值不可区分，判空请用 size
6	  peek() { return this.items[this.items.length - 1]; }
7	  get size() { return this.items.length; }
8	}
9

1	import {test} from 'node:test';
2	import assert from 'node:assert/strict';
3	import {BoundedStack} from '../src/stack.js';
4	test('容量与后进先出',()=>{const s=new BoundedStack(1);s.push(3);assert.throws(()=>s.push(4),RangeError);assert.equal(s.pop(),3);assert.equal(s.size,0);});
5	test('peek 返回栈顶且不改 size',()=>{const s=new BoundedStack(2);s.push(1);s.push(2);assert.equal(s.peek(),2);assert.equal(s.size,2);assert.equal(s.peek(),2);assert.equal(s.pop(),2);});
6	test('空栈 peek 返回 undefined',()=>{const s=new BoundedStack(2);assert.equal(s.peek(),undefined);s.push(9);assert.equal(s.pop(),9);assert.equal(s.peek(),undefined);});
